class AvgPartition:
    LIST_LENGTH = "list_length"
    PARTITION_LIMIT = "partition_limit"
    PARTITION_SIZE = "partition_size"
    REMAINDER = "remainder"

    def __init__(self, lst, limit):
        self._lst = lst
        self._limit = limit

    @property
    def lst(self):
        return self._lst

    @lst.setter
    def lst(self, value):
        self._lst = value

    @property
    def limit(self):
        return self._limit

    @limit.setter
    def limit(self, value):
        self._limit = value

    def _get_partition_size_and_remainder(self):
        size = len(self._lst) // self._limit
        remainder = len(self._lst) % self._limit
        return size, remainder

    def _calculate_start_index(self, index):
        size, remainder = self._get_partition_size_and_remainder()
        return index * size + min(index, remainder)

    def _calculate_end_index(self, index):
        size, remainder = self._get_partition_size_and_remainder()
        start = self._calculate_start_index(index)
        end = start + size
        if index + 1 <= remainder:
            end += 1
        return end

    def get(self, index):
        start = self._calculate_start_index(index)
        end = self._calculate_end_index(index)
        return self._lst[start:end]
